import { createDbFromPool } from "@ogcio/db-core";
import type { Pool } from "pg";
import { describe, expect, it } from "vitest";
import type { DB } from "../../db/schema.js";
import { FileModel } from "../../models/file-model.js";

// Exercises the REAL org-ownership access SQL generated by FileModel through a
// mocked pg pool (no live DB). See sharing-model.test.ts for the capture
// approach.
type QueryCall = { text: string; params: unknown[] };

const normalizeSql = (sql: string): string => sql.replace(/\s+/g, " ").trim();

const buildPoolMock = (rows: unknown[], calls: QueryCall[]): Pool =>
  ({
    connect: () =>
      Promise.resolve({
        query: (text: string, params: unknown[]) => {
          calls.push({ text, params });
          return Promise.resolve({ rows });
        },
        release: () => {},
      }),
  }) as unknown as Pool;

const modelWith = (rows: unknown[], calls: QueryCall[]) =>
  new FileModel(createDbFromPool<DB>(buildPoolMock(rows, calls)));

describe("FileModel.isOwnedByOrganization", () => {
  it("runs the org-ownership query and returns true on a match", async () => {
    const calls: QueryCall[] = [];
    const model = modelWith([{ id: "file-1" }], calls);

    const result = await model.isOwnedByOrganization("org-1", "file-1");

    expect(result).toBe(true);
    expect(calls).toHaveLength(1);
    expect(normalizeSql(calls[0].text)).toBe(
      "SELECT id FROM files WHERE organization_id = $1 and id = $2 LIMIT 1",
    );
    expect(calls[0].params).toEqual(["org-1", "file-1"]);
  });

  it("returns false when the file does not belong to the organization", async () => {
    const calls: QueryCall[] = [];
    const model = modelWith([], calls);

    const result = await model.isOwnedByOrganization("org-1", "file-1");

    expect(result).toBe(false);
    expect(calls[0].params).toEqual(["org-1", "file-1"]);
  });
});
